import Foundation

enum FeatureRecommendationCopy: Int, CaseIterable {
    case headerActivity
    case headerFlashcards
    case headerReview
    case headerReviewSubtitle
    case headerFlashcardSubtitle
    case headerQuestionSubtitle
    case headerDetailSubtitle
    case close
    case closeAccessibility
    case stepFormat
    case finishMatching
    case back
    case `continue`
    case notForMe
    case interested
    case applySelection
    case privacyNote
    case activitiesQuestion
    case categoriesQuestion
    case routinesQuestion
    case captureQuestion
    case activitiesSubtitle
    case categoriesSubtitle
    case routinesSubtitle
    case captureSubtitle
    case selected
    case choose
    case detailQuestion
    case detailSubtitle
    case removeTopic
    case reviewCountFormat
    case reviewExplanation
    case currentSetup
    case suggestionCountFormat
    case workflowTitle
    case noSuggestionsTitle
    case existingSetupDescription
    case workflowFormat
}

struct FeatureRecommendationStrings {
    private let copyValues: [String]
    private let activityTitles: [String]
    private let activitySubtitles: [String]
    private let categoryTitles: [String]
    private let routineTitles: [String]
    private let captureTitles: [String]
    private let detailTitles: [String]

    func text(_ key: FeatureRecommendationCopy) -> String {
        copyValues[key.rawValue]
    }

    func activityTitle(_ activity: FeatureSurveyActivity) -> String {
        activityTitles[activity.index]
    }

    func activitySubtitle(_ activity: FeatureSurveyActivity) -> String {
        activitySubtitles[activity.index]
    }

    func categoryTitle(_ category: FeatureSurveyAppCategory) -> String {
        categoryTitles[category.index]
    }

    func routineTitle(_ routine: FeatureSurveyRoutine) -> String {
        routineTitles[routine.index]
    }

    func captureTitle(_ nextStep: FeatureSurveyCaptureNextStep) -> String {
        captureTitles[nextStep.index]
    }

    func detailTitle(_ choice: FeatureSurveyDetailChoice) -> String {
        guard let index = Self.detailIDs.firstIndex(of: choice.id) else { return "" }
        return detailTitles[index]
    }

    var allUserVisibleCopy: [String] {
        copyValues + activityTitles + activitySubtitles + categoryTitles
            + routineTitles + captureTitles + detailTitles
    }

    static func localized(_ language: AppLanguage) -> Self {
        let source: String
        switch language {
        case .enUS:
            source = english
        case .ptBR:
            source = portuguese
        case .tr:
            source = turkish
        case .ru:
            source = russian
        case .es:
            source = spanish
        case .sk:
            source = slovak
        case .de:
            source = german
        case .fr:
            source = french
        case .it:
            source = italian
        case .ja:
            source = japanese
        case .ko:
            source = korean
        case .uk:
            source = ukrainian
        case .zhHans:
            source = chineseSimplified
        case .zhTW:
            source = chineseTraditionalTaiwan
        case .zhHK:
            source = chineseTraditionalHongKong
        }
        let fields = source.components(separatedBy: "¦")
        let copyCount = FeatureRecommendationCopy.allCases.count
        let activityCount = FeatureSurveyActivity.allCases.count
        let categoryCount = FeatureSurveyAppCategory.allCases.count
        let routineCount = FeatureSurveyRoutine.allCases.count
        let captureCount = FeatureSurveyCaptureNextStep.allCases.count
        let detailCount = detailIDs.count
        precondition(fields.count == copyCount + activityCount * 2 + categoryCount
                     + routineCount + captureCount + detailCount)
        var index = 0
        func take(_ count: Int) -> [String] {
            defer { index += count }
            return Array(fields[index..<(index + count)])
        }
        return Self(copyValues: take(copyCount),
                    activityTitles: take(activityCount),
                    activitySubtitles: take(activityCount),
                    categoryTitles: take(categoryCount),
                    routineTitles: take(routineCount),
                    captureTitles: take(captureCount),
                    detailTitles: take(detailCount))
    }

